bool resolve_bool_expr(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    if (!expr || !set_rtrn) {
        xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Invalid input to resolve_bool_expr\n");
        return false;
    }

    switch (expr->type) {
        case EXPR_BOOLEAN: {
            if (expr->data.boolean) {
                *set_rtrn = true;
            } else {
                *set_rtrn = false;
            }
            return true;
        }

        case EXPR_IDENTIFIER: {
            if (strcmp(expr->data.identifier, "true") == 0) {
                *set_rtrn = true;
                return true;
            } else if (strcmp(expr->data.identifier, "false") == 0) {
                *set_rtrn = false;
                return true;
            } else {
                xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR,
                        "Unknown boolean identifier: %s\n", expr->data.identifier);
                return false;
            }
        }

        case EXPR_UNARY_OP: {
            if (expr->op != OP_LOGICAL_NOT) {
                xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR,
                        "Unsupported unary operation in boolean expression\n");
                return false;
            }

            if (!resolve_bool_expr(ctx, expr->arg1, set_rtrn)) {
                return false;
            }

            *set_rtrn = !(*set_rtrn);
            return true;
        }

        default:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR,
                    "Unsupported expression type for boolean resolution\n");
            return false;
    }
}

