bool resolve_bool_expr(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    switch (expr->type) {
        case EXPR_CONSTANT:
            if (expr->u.constant.type == TYPE_BOOLEAN) {
                *set_rtrn = expr->u.constant.value.b;
                return true;
            }
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Constant is not a boolean value.");
            return false;

        case EXPR_IDENTIFIER:
            if (strcmp(expr->u.identifier.name, "true") == 0) {
                *set_rtrn = true;
                return true;
            } else if (strcmp(expr->u.identifier.name, "false") == 0) {
                *set_rtrn = false;
                return true;
            }
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unknown boolean identifier: %s.", expr->u.identifier.name);
            return false;

        case EXPR_FIELD_REF:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Field references are not supported in boolean resolution.");
            return false;

        case EXPR_UNARY_OP:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unary operations are not supported in boolean resolution.");
            return false;

        default:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unsupported expression type.");
            return false;
    }
}

bool resolve_bool_expr(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    if (!expr || !set_rtrn) {
        return false;
    }

    switch (expr->type) {
        case EXPR_BOOLEAN:
            *set_rtrn = expr->value.b;
            return true;

        case EXPR_IDENTIFIER: {
            if (strcmp(expr->value.s, "true") == 0) {
                *set_rtrn = true;
                return true;
            } else if (strcmp(expr->value.s, "false") == 0) {
                *set_rtrn = false;
                return true;
            } else {
                xkb_context_log(ctx, XKB_LOG_LEVEL_WARN,
                                "Unknown boolean identifier: '%s'", expr->value.s);
                return false;
            }
        }

        case EXPR_UNARY_OP: {
            if (expr->op != OP_NOT) {
                xkb_context_log(ctx, XKB_LOG_LEVEL_WARN,
                                "Unsupported unary operation for boolean: %d", expr->op);
                return false;
            }

            if (!resolve_bool_expr(ctx, expr->children[0], set_rtrn)) {
                return false;
            }

            *set_rtrn = !(*set_rtrn);
            return true;
        }

        default:
            xkb_context_log(ctx, XKB_LOG_LEVEL_WARN,
                            "Unsupported expression type for boolean resolution: %d", expr->type);
            return false;
    }
}

bool resolve_bool_expr(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    if (expr == NULL || set_rtrn == NULL)
        return false;

    switch (expr->type) {
        case EXPR_BOOLEAN:
            *set_rtrn = expr->value.b;
            return true;

        case EXPR_IDENTIFIER: {
            if (strcmp(expr->value.s, "true") == 0) {
                *set_rtrn = true;
                return true;
            } else if (strcmp(expr->value.s, "false") == 0) {
                *set_rtrn = false;
                return true;
            } else {
                xkb_context_log(ctx, XKB_LOG_MESSAGE_ERROR, "Unsupported boolean identifier: %s", expr->value.s);
                return false;
            }
        }

        case EXPR_UNARY_NOT:
            if (!resolve_bool_expr(ctx, expr->operand, set_rtrn))
